pub(crate) fn get_truthy_aria_hidden_attribute(element: &AnyHtmlElement) -> Option<HtmlAttribute> {
    let attribute = element.find_attribute_by_name("aria-hidden")?;
    if is_aria_hidden_value_truthy(&attribute) {
        Some(attribute)
    } else {
        None
    }
